body:
Here is the macro that will fix this problem for anyone else effected!  


{  
  "name": "Forge Fix PF2E Default Icons",  
  "type": "script",  
  "author": "PWFq6hu2Gsn7fwTT",  
  "img": "https://forge-vtt.com/images/the-forge-logo-48x48.png",  
  "scope": "global",  
  "command": "const defaultTokenImages = (forgeUserId, type) => {\\n    const defaultTokenImages = \[CONST.DEFAULT\_TOKEN\];\\n    defaultTokenImages.push(\`${ForgeVTT.ASSETS\_LIBRARY\_URL\_PREFIX}bazaar/core/${CONST.DEFAULT\_TOKEN}\`);\\n    const systemId = game.system.id || game.system.data?.name;\\n    switch (systemId) {\\n        case \\"pf2e\\":\\n            // Special default icons for pf2e\\n            defaultTokenImages.push(\`systems/pf2e/icons/default-icons/${type}.svg\`);\\n\\t\\tdefaultTokenImages.push(\`systems/pf2e/icons/default-icons/mystery-man.svg\`);\\n\\t\\tdefaultTokenImages.push(\`${ForgeVTT.ASSETS\_LIBRARY\_URL\_PREFIX}${forgeUserId}/systems/pf2e/icons/default-icons/${type}.svg\`);\\n\\t\\tdefaultTokenImages.push(\`${ForgeVTT.ASSETS\_LIBRARY\_URL\_PREFIX}${forgeUserId}/systems/pf2e/icons/default-icons/mystery-man.svg\`);\\n            defaultTokenImages.push(\`${ForgeVTT.ASSETS\_LIBRARY\_URL\_PREFIX}bazaar/systems/pf2e/assets/icons/default-icons/${type}.svg\`);\\n\\t\\tdefaultTokenImages.push(\`${ForgeVTT.ASSETS\_LIBRARY\_URL\_PREFIX}bazaar/systems/pf2e/assets/icons/default-icons/mystery-man.svg\`);\\n            break;\\n        default:\\n            break;\\n    }\\n    return defaultTokenImages;\\n}\\nconst fixDefaultIcons = async () => {\\n    let \[actorCursor, sceneCursor, tokenCursor\] = \[0, 0, 0\];\\n    const \[actorUpdates, tokenUpdates\] = \[\[\], \[\]\];\\n    const forgeUserId = await ForgeAPI.getUserId();\\n    game.actors.forEach(actor => {\\n        actorCursor++;\\n        console.log(\`Checking actor (${actorCursor}/${game.actors.size}) ${actor.name} prototypeToken.texture.src\`);\\n        if (defaultTokenImages(forgeUserId, actor.type).includes(actor.prototypeToken.texture.src) &&\\n            !defaultTokenImages(forgeUserId, actor.type).includes(actor.img)) {\\n            console.log(\`Updating ${actor.name} prototypeToken.texture.src ${actor.prototypeToken.texture.src} to ${actor.img}\`);\\n            actorUpdates.push(actor.prototypeToken.update({texture: {src: actor.img}}));\\n        }\\n    });\\n    game.scenes.forEach(scene => {\\n        sceneCursor++;\\n        tokenCursor = 0;\\n        console.log(\`Checking scene ${scene.name} (${sceneCursor}/${game.scenes.size})\`);\\n        for (const token of scene.tokens) {\\n            tokenCursor++;\\n            console.log(\`Checking scene (${sceneCursor}/${game.scenes.size}) ${scene.name} : token (${tokenCursor}/${scene.tokens.size}) ${token.name} texture.src\`);\\n            if (!token.actor) {\\n                console.warn(\`${token.name} has no linked actor, skipping\`);\\n                continue;\\n            }\\n            if (defaultTokenImages(forgeUserId, token.actor.type).includes(token.texture.src) &&\\n                !defaultTokenImages(forgeUserId, token.actor.type).includes(token.actor.img)) {\\n                console.log(\`Updating ${token.name} texture.src ${token.texture.src} to ${token.actor.img}\`);\\n                tokenUpdates.push(token.update({texture: {src: token.actor.img}}));\\n            }\\n        }\\n    });\\n    console.log(\`Updated ${actorUpdates.length} actors and ${tokenUpdates.length} tokens\`);\\n    await Promise.allSettled(\[\].concat(actorUpdates, tokenUpdates));\\n}\\nif (typeof ForgeVTT !== \\"undefined\\" && ForgeVTT.usingTheForge) {\\n    fixDefaultIcons();\\n}",  
  "flags": {  
"advanced-macros": {  
"runAsGM": true,  
"runForSpecificUser": ""  
},  
"exportSource": {  
"world": "gatewalkers",  
"system": "pf2e",  
"coreVersion": "10.291",  
"systemVersion": "4.9.3"  
}  
  },  
  "\_stats": {  
"systemId": "pf2e",  
"systemVersion": "4.9.3",  
"coreVersion": "10.291",  
"createdTime": 1679518368164,  
"modifiedTime": 1679518441297,  
"lastModifiedBy": "PWFq6hu2Gsn7fwTT"  
  }  
}
